namespace CodeLens.Infrastructure.AI;

using System.Text;
using System.Text.RegularExpressions;

/// <summary>
/// Sanitizes and validates Mermaid.js diagrams generated by LLMs to ensure
/// error-free client-side SVG rendering across Mermaid 12+.
/// </summary>
public static partial class MermaidSanitizer
{
    private static readonly string[] ValidDiagramHeaders =
    [
        "flowchart",
        "graph",
        "classDiagram",
        "sequenceDiagram",
        "erDiagram",
        "stateDiagram",
        "journey",
        "gantt",
        "pie",
        "gitGraph",
        "c4context",
        "c4container",
        "c4component"
    ];

    [GeneratedRegex(@"^```(?:mermaid)?\s*", RegexOptions.IgnoreCase | RegexOptions.Multiline)]
    private static partial Regex CodeFenceStartRegex();

    [GeneratedRegex(@"\s*```\s*$", RegexOptions.Multiline)]
    private static partial Regex CodeFenceEndRegex();

    // 1. Cylinder: id[( label )]
    [GeneratedRegex(@"([a-zA-Z0-9_-]+)\[\(\s*(.*?)\s*\)\]")]
    private static partial Regex CylinderShapeRegex();

    // 2. Stadium: id([ label ])
    [GeneratedRegex(@"([a-zA-Z0-9_-]+)\(\[\s*(.*?)\s*\]\)")]
    private static partial Regex StadiumShapeRegex();

    // 3. Subroutine: id[[ label ]]
    [GeneratedRegex(@"([a-zA-Z0-9_-]+)\[\[\s*(.*?)\s*\]\]")]
    private static partial Regex SubroutineShapeRegex();

    // 4. Hexagon: id{{ label }}
    [GeneratedRegex(@"([a-zA-Z0-9_-]+)\{\{\s*(.*?)\s*\}\}")]
    private static partial Regex HexagonShapeRegex();

    // 5. Double Circle: id(( label ))
    [GeneratedRegex(@"([a-zA-Z0-9_-]+)\(\(\s*(.*?)\s*\)\)")]
    private static partial Regex DoubleCircleShapeRegex();

    // 6. Standard Rectangle: id[ label ] (excluding [[ and [( and )] and ]])
    [GeneratedRegex(@"([a-zA-Z0-9_-]+)(?<!\[)\[(?![\[(])\s*(.*?)\s*\](?!\])")]
    private static partial Regex StandardRectangleRegex();

    // 7. Standard Rounded: id( label ) (excluding (( and ([ and ]) and ))
    [GeneratedRegex(@"([a-zA-Z0-9_-]+)(?<!\()\((?![[(])\s*(.*?)\s*\)(?!\))")]
    private static partial Regex StandardRoundedRegex();

    // 8. Arrow label: -->|label|
    [GeneratedRegex(@"(--+>|==+>|-\.+->)\|([^|\n]+)\|")]
    private static partial Regex ArrowLabelRegex();

    [GeneratedRegex(@"^(\s*subgraph\s+)(.+)$", RegexOptions.IgnoreCase)]
    private static partial Regex SubgraphTitleRegex();

    /// <summary>
    /// Cleans and sanitizes raw Mermaid diagram text.
    /// </summary>
    public static string Sanitize(string? rawMermaid, string repoName = "Repository")
    {
        if (string.IsNullOrWhiteSpace(rawMermaid))
        {
            return BuildFallbackDiagram(repoName);
        }

        var text = rawMermaid.Trim();

        // 1. Remove markdown fences (```mermaid ... ```)
        text = CodeFenceStartRegex().Replace(text, string.Empty);
        text = CodeFenceEndRegex().Replace(text, string.Empty);
        text = text.Trim();

        if (string.IsNullOrWhiteSpace(text))
        {
            return BuildFallbackDiagram(repoName);
        }

        // 2. Normalize line endings and filter out empty / invalid noise
        var rawLines = text.Split(["\r\n", "\r", "\n"], StringSplitOptions.None)
            .Select(l => l.TrimEnd())
            .Select(l => l.TrimStart('>', ' ', '*', '-'))
            .ToList();

        // 3. Ensure a valid diagram header is present
        var firstContentIndex = rawLines.FindIndex(l => !string.IsNullOrWhiteSpace(l) && !l.TrimStart().StartsWith("%%"));
        if (firstContentIndex == -1)
        {
            return BuildFallbackDiagram(repoName);
        }

        var headerLine = rawLines[firstContentIndex].Trim();
        var hasValidHeader = ValidDiagramHeaders.Any(h => headerLine.StartsWith(h, StringComparison.OrdinalIgnoreCase));

        if (!hasValidHeader)
        {
            rawLines.Insert(0, "flowchart TD");
        }

        // 4. Multi-line node joining & auto-closing of unclosed brackets on a line
        var joinedLines = new List<string>();
        var buffer = new StringBuilder();
        var insideOpenDelimiter = false;

        for (var i = 0; i < rawLines.Count; i++)
        {
            var line = rawLines[i];
            var trimmed = line.Trim();

            if (string.IsNullOrWhiteSpace(trimmed) || trimmed.StartsWith("%%"))
            {
                if (!insideOpenDelimiter)
                {
                    joinedLines.Add(line);
                }
                continue;
            }

            if (insideOpenDelimiter)
            {
                buffer.Append(' ').Append(trimmed);
                var cur = buffer.ToString();
                if (cur.Contains(']') || cur.Contains(')') || cur.Contains('}'))
                {
                    joinedLines.Add(cur);
                    buffer.Clear();
                    insideOpenDelimiter = false;
                }
                continue;
            }

            // Count delimiters
            var openBrackets = trimmed.Count(c => c == '[');
            var closeBrackets = trimmed.Count(c => c == ']');
            var openParens = trimmed.Count(c => c == '(');
            var closeParens = trimmed.Count(c => c == ')');

            // If an unclosed bracket exists:
            if (openBrackets > closeBrackets)
            {
                // If next line exists and looks like a continuation (not starting with subgraph, end, or node arrow)
                if (i + 1 < rawLines.Count && !IsNewStatement(rawLines[i + 1].Trim()))
                {
                    buffer.Append(line);
                    insideOpenDelimiter = true;
                    continue;
                }
                else
                {
                    // Auto-close unclosed bracket: "A[View Visual Spending " -> "A[View Visual Spending]"
                    joinedLines.Add(line + "]");
                    continue;
                }
            }

            if (openParens > closeParens && !trimmed.Contains("-->") && !trimmed.Contains("---"))
            {
                if (i + 1 < rawLines.Count && !IsNewStatement(rawLines[i + 1].Trim()))
                {
                    buffer.Append(line);
                    insideOpenDelimiter = true;
                    continue;
                }
                else
                {
                    joinedLines.Add(line + ")");
                    continue;
                }
            }

            joinedLines.Add(line);
        }

        if (buffer.Length > 0)
        {
            joinedLines.Add(buffer.ToString() + "]");
        }

        // 5. Line-by-line sanitization of node labels and relationships
        var sanitizedLines = new List<string>();
        var subgraphCount = 0;
        var endCount = 0;

        foreach (var rawLine in joinedLines)
        {
            var line = rawLine;

            // Track subgraphs
            var trimmed = line.Trim();
            if (trimmed.StartsWith("subgraph", StringComparison.OrdinalIgnoreCase))
            {
                subgraphCount++;
                // Quote subgraph title if unquoted and contains spaces or special characters
                line = SanitizeSubgraphTitle(line);
            }
            else if (trimmed.Equals("end", StringComparison.OrdinalIgnoreCase))
            {
                endCount++;
            }
            else if (!trimmed.StartsWith("%%") && !ValidDiagramHeaders.Any(h => trimmed.StartsWith(h, StringComparison.OrdinalIgnoreCase)))
            {
                line = SanitizeDiagramLine(line);
            }

            sanitizedLines.Add(line);
        }

        // 6. Balance missing 'end' statements for subgraphs
        while (endCount < subgraphCount)
        {
            sanitizedLines.Add("  end");
            endCount++;
        }

        var result = string.Join("\n", sanitizedLines).Trim();
        return string.IsNullOrWhiteSpace(result) ? BuildFallbackDiagram(repoName) : result;
    }

    private static bool IsNewStatement(string trimmed)
    {
        if (string.IsNullOrWhiteSpace(trimmed)) return false;
        return trimmed.StartsWith("subgraph", StringComparison.OrdinalIgnoreCase)
            || trimmed.Equals("end", StringComparison.OrdinalIgnoreCase)
            || Regex.IsMatch(trimmed, @"^[a-zA-Z0-9_-]+\s*(--+>|==+>|-\.+->)");
    }

    private static string SanitizeSubgraphTitle(string line)
    {
        var match = SubgraphTitleRegex().Match(line);
        if (!match.Success) return line;

        var prefix = match.Groups[1].Value;
        var title = match.Groups[2].Value.Trim();

        // If title is already quoted or bracketed like subgraph SubName ["Title"] or subgraph "Title"
        if (title.StartsWith("\"") && title.EndsWith("\"")) return line;
        if (title.Contains('[')) return line;

        // If title has spaces or punctuation, sanitize into subgraph id ["Title"]
        if (title.Any(c => char.IsWhiteSpace(c) || char.IsPunctuation(c)))
        {
            var safeId = Regex.Replace(title, @"[^a-zA-Z0-9_]", "_");
            var cleanTitle = title.Replace("\"", "'");
            return $"{prefix}{safeId}[\"{cleanTitle}\"]";
        }

        return line;
    }

    private static string CleanInnerLabel(string text)
    {
        var trimmed = text.Trim().Trim('\"');
        return trimmed.Replace("\"", "'");
    }

    private static string SanitizeDiagramLine(string line)
    {
        if (string.IsNullOrWhiteSpace(line)) return line;

        var l = line;

        // 1. Cylinder: id[( label )] -> id[("clean")]
        l = CylinderShapeRegex().Replace(l, m => $"{m.Groups[1].Value}[(\"{CleanInnerLabel(m.Groups[2].Value)}\")]");

        // 2. Stadium: id([ label ]) -> id(["clean"])
        l = StadiumShapeRegex().Replace(l, m => $"{m.Groups[1].Value}([\"{CleanInnerLabel(m.Groups[2].Value)}\"])");

        // 3. Subroutine: id[[ label ]] -> id[["clean"]]
        l = SubroutineShapeRegex().Replace(l, m => $"{m.Groups[1].Value}[[\"{CleanInnerLabel(m.Groups[2].Value)}\"]]");

        // 4. Hexagon: id{{ label }} -> id{{"clean"}}
        l = HexagonShapeRegex().Replace(l, m => $"{m.Groups[1].Value}{{{{\"{CleanInnerLabel(m.Groups[2].Value)}\"}}}}");

        // 5. Double Circle: id(( label )) -> id(("clean"))
        l = DoubleCircleShapeRegex().Replace(l, m => $"{m.Groups[1].Value}((\"{CleanInnerLabel(m.Groups[2].Value)}\"))");

        // 6. Standard Rectangle: id[ label ] (excluding [[ and [( and )] and ]])
        l = StandardRectangleRegex().Replace(l, m => $"{m.Groups[1].Value}[\"{CleanInnerLabel(m.Groups[2].Value)}\"]");

        // 7. Standard Rounded: id( label ) (excluding (( and ([ and ]) and ))
        l = StandardRoundedRegex().Replace(l, m =>
        {
            var inner = m.Groups[2].Value;
            if (inner.Contains("-->") || inner.Contains("---")) return m.Value;
            return $"{m.Groups[1].Value}(\"{CleanInnerLabel(inner)}\")";
        });

        // 8. Arrow label: -->|label| -> -->|"clean"|
        l = ArrowLabelRegex().Replace(l, m => $"{m.Groups[1].Value}|\"{CleanInnerLabel(m.Groups[2].Value)}\"|");

        return l;
    }

    /// <summary>
    /// Generates a clean, guaranteed-renderable fallback architecture diagram.
    /// </summary>
    public static string BuildFallbackDiagram(string repoName)
    {
        var safeName = string.IsNullOrWhiteSpace(repoName) ? "Repository" : repoName.Replace("\"", "'");
        return $"""
        flowchart TD
          Client["Web / Client Application"]
          API["{safeName} API & Core Engine"]
          Analysis["Analysis & Telemetry Engine"]
          Storage[("Storage & Persistence")]

          Client --> API
          API --> Analysis
          API --> Storage
          Analysis --> Storage
        """;
    }
}

